import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { supabase } from '../../supabaseClient';
import { useAuth } from '../../context/AuthContext';
import ReactQuill from 'react-quill';
import 'react-quill/dist/quill.snow.css';
import { ArrowLeft, Save, Eye, Image as ImageIcon, X } from 'lucide-react';
import './BlogEditor.css';

function BlogEditor() {
  const { id } = useParams();
  const navigate = useNavigate();
  const { user } = useAuth();
  const isEditMode = Boolean(id);

  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [message, setMessage] = useState('');

  // Post data
  const [title, setTitle] = useState('');
  const [slug, setSlug] = useState('');
  const [excerpt, setExcerpt] = useState('');
  const [content, setContent] = useState('');
  const [featuredImage, setFeaturedImage] = useState('');
  const [status, setStatus] = useState('draft');
  const [seoTitle, setSeoTitle] = useState('');
  const [seoDescription, setSeoDescription] = useState('');
  const [seoKeywords, setSeoKeywords] = useState('');

  // Categories and tags
  const [categories, setCategories] = useState([]);
  const [tags, setTags] = useState([]);
  const [selectedCategories, setSelectedCategories] = useState([]);
  const [selectedTags, setSelectedTags] = useState([]);

  // Image upload
  const [uploadingImage, setUploadingImage] = useState(false);

  const loadCategoriesAndTags = useCallback(async () => {
    try {
      const [categoriesRes, tagsRes] = await Promise.all([
        supabase.from('blog_categories').select('*').order('name'),
        supabase.from('blog_tags').select('*').order('name')
      ]);

      if (categoriesRes.data) setCategories(categoriesRes.data);
      if (tagsRes.data) setTags(tagsRes.data);
    } catch (error) {
      console.error('Error loading categories/tags:', error);
    }
  }, []);

  const loadPost = useCallback(async () => {
    try {
      setLoading(true);

      const { data: post, error } = await supabase
        .from('blog_posts')
        .select(`
          *,
          blog_post_categories(category_id),
          blog_post_tags(tag_id)
        `)
        .eq('id', id)
        .single();

      if (error) throw error;

      setTitle(post.title);
      setSlug(post.slug);
      setExcerpt(post.excerpt || '');
      setContent(post.content);
      setFeaturedImage(post.featured_image || '');
      setStatus(post.status);
      setSeoTitle(post.seo_title || '');
      setSeoDescription(post.seo_description || '');
      setSeoKeywords(post.seo_keywords || '');
      setSelectedCategories(post.blog_post_categories?.map(c => c.category_id) || []);
      setSelectedTags(post.blog_post_tags?.map(t => t.tag_id) || []);
    } catch (error) {
      console.error('Error loading post:', error);
      setMessage('Error loading post');
    } finally {
      setLoading(false);
    }
  }, [id]);

  useEffect(() => {
    loadCategoriesAndTags();
    if (isEditMode) {
      loadPost();
    }
  }, [isEditMode, loadCategoriesAndTags, loadPost]);

  // Auto-generate slug from title
  useEffect(() => {
    if (!isEditMode && title) {
      const generatedSlug = title
        .toLowerCase()
        .replace(/[^\w\s-]/g, '')
        .replace(/\s+/g, '-')
        .replace(/-+/g, '-')
        .trim();
      setSlug(generatedSlug);
    }
  }, [title, isEditMode]);

  const handleImageUpload = async (e) => {
    const file = e.target.files?.[0];
    if (!file) return;

    try {
      setUploadingImage(true);

      const fileExt = file.name.split('.').pop();
      const fileName = `${Date.now()}-${Math.random().toString(36).substring(7)}.${fileExt}`;
      const filePath = `blog-images/${fileName}`;

      const { error: uploadError } = await supabase.storage
        .from('public-files')
        .upload(filePath, file);

      if (uploadError) throw uploadError;

      const { data: { publicUrl } } = supabase.storage
        .from('public-files')
        .getPublicUrl(filePath);

      setFeaturedImage(publicUrl);
      setMessage('✅ Image uploaded successfully');
      setTimeout(() => setMessage(''), 3000);
    } catch (error) {
      console.error('Error uploading image:', error);
      setMessage('❌ Error uploading image');
    } finally {
      setUploadingImage(false);
    }
  };

  const calculateReadingTime = (text) => {
    const words = text.trim().split(/\s+/).length;
    return Math.max(1, Math.round(words / 200));
  };

  const handleSave = async (publishNow = false) => {
    if (!title.trim()) {
      setMessage('❌ Title is required');
      return;
    }

    if (!content.trim()) {
      setMessage('❌ Content is required');
      return;
    }

    try {
      setSaving(true);

      const postData = {
        title: title.trim(),
        slug: slug.trim(),
        excerpt: excerpt.trim() || null,
        content: content.trim(),
        featured_image: featuredImage || null,
        author_id: user.id,
        status: publishNow ? 'published' : status,
        published_at: publishNow ? new Date().toISOString() : (status === 'published' ? new Date().toISOString() : null),
        reading_time: calculateReadingTime(content),
        seo_title: seoTitle.trim() || null,
        seo_description: seoDescription.trim() || null,
        seo_keywords: seoKeywords.trim() || null
      };

      let postId = id;

      if (isEditMode) {
        // Update existing post
        const { error } = await supabase
          .from('blog_posts')
          .update(postData)
          .eq('id', id);

        if (error) throw error;
      } else {
        // Create new post
        const { data, error } = await supabase
          .from('blog_posts')
          .insert([postData])
          .select()
          .single();

        if (error) throw error;
        postId = data.id;
      }

      // Update categories
      await supabase.from('blog_post_categories').delete().eq('post_id', postId);
      if (selectedCategories.length > 0) {
        const categoryInserts = selectedCategories.map(catId => ({
          post_id: postId,
          category_id: catId
        }));
        await supabase.from('blog_post_categories').insert(categoryInserts);
      }

      // Update tags
      await supabase.from('blog_post_tags').delete().eq('post_id', postId);
      if (selectedTags.length > 0) {
        const tagInserts = selectedTags.map(tagId => ({
          post_id: postId,
          tag_id: tagId
        }));
        await supabase.from('blog_post_tags').insert(tagInserts);
      }

      setMessage(`✅ Post ${publishNow ? 'published' : 'saved'} successfully!`);
      setTimeout(() => {
        navigate('/dashboard/admin/blog');
      }, 1500);
    } catch (error) {
      console.error('Error saving post:', error);
      setMessage('❌ Error saving post: ' + error.message);
    } finally {
      setSaving(false);
    }
  };

  const modules = useMemo(() => ({
    toolbar: [
      [{ 'header': [1, 2, 3, false] }],
      ['bold', 'italic', 'underline', 'strike'],
      [{ 'list': 'ordered'}, { 'list': 'bullet' }],
      [{ 'indent': '-1'}, { 'indent': '+1' }],
      ['link', 'image', 'video'],
      [{ 'align': [] }],
      ['blockquote', 'code-block'],
      ['clean']
    ]
  }), []);

  if (loading) {
    return <div className="loading">Loading post...</div>;
  }

  return (
    <div className="blog-editor-container">
      <div className="blog-editor-header">
        <button className="btn-back" onClick={() => navigate('/dashboard/admin/blog')}>
          <ArrowLeft size={20} />
          Back to Posts
        </button>

        <div className="editor-actions">
          <button
            className="btn-secondary"
            onClick={() => handleSave(false)}
            disabled={saving}
          >
            <Save size={18} />
            {saving ? 'Saving...' : 'Save Draft'}
          </button>
          <button
            className="btn-primary"
            onClick={() => handleSave(true)}
            disabled={saving}
          >
            <Eye size={18} />
            {isEditMode && status === 'published' ? 'Update & Publish' : 'Publish'}
          </button>
        </div>
      </div>

      {message && (
        <div className={`message ${message.includes('✅') ? 'message-success' : 'message-error'}`}>
          {message}
        </div>
      )}

      <div className="blog-editor-content">
        {/* Main Editor Column */}
        <div className="editor-main">
          <div className="form-group">
            <label className="form-label">Title *</label>
            <input
              type="text"
              className="form-input form-input-large"
              placeholder="Enter post title..."
              value={title}
              onChange={(e) => setTitle(e.target.value)}
            />
          </div>

          <div className="form-group">
            <label className="form-label">URL Slug *</label>
            <input
              type="text"
              className="form-input"
              placeholder="post-url-slug"
              value={slug}
              onChange={(e) => setSlug(e.target.value)}
            />
            <small className="form-hint">URL: /blog/{slug || 'post-url-slug'}</small>
          </div>

          <div className="form-group">
            <label className="form-label">Excerpt</label>
            <textarea
              className="form-textarea"
              rows="3"
              placeholder="Brief description of the post (optional)..."
              value={excerpt}
              onChange={(e) => setExcerpt(e.target.value)}
            />
          </div>

          <div className="form-group">
            <label className="form-label">Content *</label>
            <ReactQuill
              theme="snow"
              value={content}
              onChange={setContent}
              modules={modules}
              placeholder="Write your blog post content here..."
            />
          </div>

          {/* SEO Section */}
          <div className="seo-section">
            <h3 className="section-title">SEO Settings</h3>

            <div className="form-group">
              <label className="form-label">SEO Title (max 60 characters)</label>
              <input
                type="text"
                className="form-input"
                maxLength="60"
                placeholder="Optimized title for search engines"
                value={seoTitle}
                onChange={(e) => setSeoTitle(e.target.value)}
              />
              <small className="form-hint">{seoTitle.length}/60 characters</small>
            </div>

            <div className="form-group">
              <label className="form-label">SEO Description (max 160 characters)</label>
              <textarea
                className="form-textarea"
                rows="2"
                maxLength="160"
                placeholder="Brief description for search results"
                value={seoDescription}
                onChange={(e) => setSeoDescription(e.target.value)}
              />
              <small className="form-hint">{seoDescription.length}/160 characters</small>
            </div>

            <div className="form-group">
              <label className="form-label">Keywords (comma-separated)</label>
              <input
                type="text"
                className="form-input"
                placeholder="3d rendering, architecture, visualization"
                value={seoKeywords}
                onChange={(e) => setSeoKeywords(e.target.value)}
              />
            </div>
          </div>
        </div>

        {/* Sidebar */}
        <div className="editor-sidebar">
          {/* Featured Image */}
          <div className="sidebar-section">
            <h3 className="section-title">Featured Image</h3>
            {featuredImage ? (
              <div className="featured-image-preview">
                <img src={featuredImage} alt="Featured" />
                <button
                  className="btn-remove-image"
                  onClick={() => setFeaturedImage('')}
                >
                  <X size={16} />
                </button>
              </div>
            ) : (
              <label className="image-upload-box">
                <input
                  type="file"
                  accept="image/*"
                  onChange={handleImageUpload}
                  disabled={uploadingImage}
                />
                <ImageIcon size={32} />
                <span>{uploadingImage ? 'Uploading...' : 'Click to upload'}</span>
              </label>
            )}
          </div>

          {/* Categories */}
          <div className="sidebar-section">
            <h3 className="section-title">Categories</h3>
            <div className="checkbox-list">
              {categories.map(category => (
                <label key={category.id} className="checkbox-label">
                  <input
                    type="checkbox"
                    checked={selectedCategories.includes(category.id)}
                    onChange={(e) => {
                      if (e.target.checked) {
                        setSelectedCategories([...selectedCategories, category.id]);
                      } else {
                        setSelectedCategories(selectedCategories.filter(id => id !== category.id));
                      }
                    }}
                  />
                  <span>{category.name}</span>
                </label>
              ))}
            </div>
          </div>

          {/* Tags */}
          <div className="sidebar-section">
            <h3 className="section-title">Tags</h3>
            <div className="checkbox-list">
              {tags.map(tag => (
                <label key={tag.id} className="checkbox-label">
                  <input
                    type="checkbox"
                    checked={selectedTags.includes(tag.id)}
                    onChange={(e) => {
                      if (e.target.checked) {
                        setSelectedTags([...selectedTags, tag.id]);
                      } else {
                        setSelectedTags(selectedTags.filter(id => id !== tag.id));
                      }
                    }}
                  />
                  <span>{tag.name}</span>
                </label>
              ))}
            </div>
          </div>

          {/* Reading Time */}
          <div className="sidebar-section">
            <h3 className="section-title">Reading Time</h3>
            <p className="reading-time">{calculateReadingTime(content)} min read</p>
          </div>
        </div>
      </div>
    </div>
  );
}

export default BlogEditor;
